using NuclearOptionObserver;
static class FlightHoldTests
{
 static void Check(bool ok){if(!ok)throw new Exception("flight hold assertion failed");}
 public static (string Name,Action Body)[] Cases=>new (string,Action)[]{
  ("master off never captures or owns aircraft input",()=>{var g=new HoldLifecycle();Check(!g.Evaluate(false,HoldReason.Map,1,false,true)&&!g.Active);Check(AxisArbiter.Choose(false,false,false)==AxisOwner.Native);}),
  ("reason overlap and map camera transitions capture targets only once",()=>{var g=new HoldLifecycle();Check(g.Evaluate(true,HoldReason.Map,1,false,true)&&g.Engagement==1);Check(!g.Evaluate(true,HoldReason.Map|HoldReason.ExternalView,2,false,true));g.Evaluate(true,HoldReason.None,3,false,true);Check(g.Active);g.Evaluate(true,HoldReason.ExternalView,4,false,true);Check(g.Active&&g.Engagement==1);g.Evaluate(true,HoldReason.None,5,false,true);g.Evaluate(true,HoldReason.None,6,false,true);Check(!g.Active);}),
  ("manual override latches until full trigger cycle or explicit rearm",()=>{var g=new HoldLifecycle();g.Evaluate(true,HoldReason.Map,1,false,true);g.Override();Check(g.Latched&&!g.Active&&!g.Evaluate(true,HoldReason.Map,2,false,true));g.Evaluate(true,HoldReason.None,3,false,true);Check(g.Latched);g.Evaluate(true,HoldReason.None,4,false,true);Check(!g.Latched&&g.Evaluate(true,HoldReason.Map,5,false,true));g.Override();g.Rearm();Check(g.Evaluate(true,HoldReason.Map,6,false,true));}),
  ("pause freezes lifecycle without recapture and invalid active state latches",()=>{var g=new HoldLifecycle();g.Evaluate(true,HoldReason.Map,1,false,true);g.Evaluate(true,HoldReason.None,2,true,false);Check(g.Active&&g.Engagement==1);g.Evaluate(true,HoldReason.Map,3,false,false);Check(!g.Active&&g.Latched);}),
  ("one arbiter gives native override priority over hold over fullscreen fallback",()=>{Check(AxisArbiter.Choose(true,true,true)==AxisOwner.Native);Check(AxisArbiter.Choose(false,true,true)==AxisOwner.Hold);Check(AxisArbiter.Choose(false,false,true)==AxisOwner.FullscreenNeutral);}),
  ("throttle handover reverses collective and negative mapping exactly",()=>{Check(ThrottleHandover.Convert(.7f,false,false,false,out var a)&&Math.Abs(a-.7f)<1e-6);Check(ThrottleHandover.Convert(.7f,true,true,false,out a)&&Math.Abs(a-.3f)<1e-6);Check(ThrottleHandover.Convert(.7f,true,true,true,out a)&&Math.Abs(a+.4f)<1e-6);Check(!ThrottleHandover.Convert(float.NaN,false,false,false,out _));}),
  ("manual raw axes override but Pan Tilt are not flight input fields",()=>{var entry=new RawFlightInput{Enabled=true,Throttle=.6f,Custom=1};var p=new ManualOverridePolicy(entry);Check(!p.Detect(entry));var x=entry;x.Pitch=.3f;Check(p.Detect(x));x=entry;x.Roll=-.3f;Check(p.Detect(x));x=entry;x.Yaw=.2f;Check(p.Detect(x));}),
  ("absolute throttle nonzero is not override but movement and relative activity are",()=>{var x=new RawFlightInput{Enabled=true,Throttle=.7f,Custom=1};var p=new ManualOverridePolicy(x);Check(!p.Detect(x));x.Throttle=.8f;Check(p.Detect(x));x.Throttle=.7f;x.RelativeThrottle=true;Check(p.Detect(x));}),
  ("custom vector brake gear engine and recovery controls cancel hold",()=>{var x=new RawFlightInput{Enabled=true,Throttle=.5f,Custom=1,AxisModifier=false};var p=new ManualOverridePolicy(x);var y=x;y.Custom=.8f;Check(p.Detect(y));foreach(int i in new[]{0,1,2,3,4}){y=x;if(i==0)y.Brake=true;if(i==1)y.Gear=true;if(i==2)y.Engine=true;if(i==3)y.Eject=true;if(i==4)y.Assist=true;Check(p.Detect(y));}}),
  ("RMB or native Free Look Pan Tilt never count as virtual flight override",()=>{Check(!ManualOverridePolicy.VirtualStick(true,true,false,true,false,10,10));Check(!ManualOverridePolicy.VirtualStick(true,true,false,false,true,10,10));Check(!ManualOverridePolicy.VirtualStick(true,true,true,false,false,10,10));Check(ManualOverridePolicy.VirtualStick(true,true,false,false,false,1,0));}),
  ("only native cockpit Pan Tilt is virtual flight intent; orbit TV stay view while joystick overrides",()=>{Check(ManualOverridePolicy.VirtualStick(true,true,false,false,false,2,0));Check(!ManualOverridePolicy.VirtualStick(true,false,false,false,false,2,0));Check(!ManualOverridePolicy.VirtualStick(true,false,false,false,false,0,2));var baseline=new RawFlightInput{Enabled=true,Throttle=.6f,Custom=1};var policy=new ManualOverridePolicy(baseline);baseline.Roll=.4f;Check(policy.Detect(baseline));}),
  ("manual composite flight intent wins simultaneous mapping conflict and neutral drain",()=>{Check(ManualOverridePolicy.Response(true,true)==HoldInputResponse.Manual);Check(ManualOverridePolicy.Response(false,true)==HoldInputResponse.SafetyRelease);Check(ManualOverridePolicy.ShouldObserve(false,false,true));var baseline=new RawFlightInput{Enabled=true,Throttle=.6f,Custom=1};var p=new ManualOverridePolicy(baseline);baseline.Roll=.5f;bool manual=ManualOverridePolicy.ShouldObserve(false,false,true)&&p.Detect(baseline);Check(AxisArbiter.Choose(manual,false,true)==AxisOwner.Native);}),
  ("hold status geometry blocks only its drawn visible pixels after mouse Y conversion",()=>{var h=HoldHudLayout.Clamp(1920,1080);Check(h.Width==640&&h.Height==80);Check(h.BlocksPointer(true,h.X,1080-h.Y,1080));Check(h.BlocksPointer(true,h.X+h.Width,1080-h.Y-h.Height,1080));Check(!h.BlocksPointer(false,h.X,1080-h.Y,1080));Check(!h.BlocksPointer(true,h.X+h.Width+1,1080-h.Y,1080));var tiny=HoldHudLayout.Clamp(200,40);Check(tiny.X>=0&&tiny.Y>=0&&tiny.X+tiny.Width<=200&&tiny.Y+tiny.Height<=40);}),
  ("raw cache reset rejects independently replaced control and Rewired player objects",()=>{object inputs=new(),player=new();Check(StoredSteering.SameInputObjects(inputs,inputs,player,player));Check(!StoredSteering.SameInputObjects(inputs,new(),player,player));Check(!StoredSteering.SameInputObjects(inputs,inputs,player,new()));Check(!StoredSteering.SameInputObjects(null!,null!,player,player));Check(!StoredSteering.SameInputObjects(inputs,inputs,null!,null!));}),
  ("ownership transition discards stored mouse-era axes before map can replay them",()=>{float pitch=.45f,roll=-.7f,yaw=.2f;StoredSteering.Clear(ref pitch,ref roll,ref yaw);Check(pitch==0&&roll==0&&yaw==0);StoredSteering.Clear(ref pitch,ref roll,ref yaw);Check(pitch==0&&roll==0&&yaw==0);}),
  ("disabled UI input zeros do not masquerade as deliberate throttle movement",()=>{var p=new ManualOverridePolicy(new RawFlightInput{Enabled=true,Throttle=.8f,Custom=1});Check(!p.Detect(new RawFlightInput{Enabled=false}));}),
 };
}
